mapper.select:
SELECT COUNT(*)
FROM reservations
WHERE id = #{reservationId}
    AND guest_user_id = #{memberId}

SELECT place_id
FROM reservations
WHERE id = #{reservationId}

SELECT COUNT(*)
FROM reviews r
JOIN reservations res ON r.reservation_id = res.id
WHERE r.id = #{reviewId}
    AND res.guest_user_id = #{memberId}
    AND r.deleted_at IS NULL

mapper.update:
UPDATE reviews
SET
    rating = #{rating},
    content = #{content}
WHERE id = #{reviewId}

UPDATE reviews
SET deleted_at = #{deletedAt}
WHERE id = #{reviewId}
